from taf.rfrl.procedures.resources.python.bts.components.du.du import Du
from taf.rfrl.procedures.resources.python.bts.utils.errors import ErrorHistory
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import ResultError
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import pretty_log, log_info


@pretty_log
def enter_test_dedicated_state(du: Du):
    """
    Enters Test Dedicated State on given DU.
    :param du: DU which should be in Test Dedicated State
    :raises UnexpectedState: if DU doesn't reach Test Dedicated State
    :raises ResultError: if any other step fails
    """
    log_info(f'Entering Test Dedicated State on {du.name}',
             to_console=True)
    du.cu.allow_alarm(fault_id='7104',
                      fault_name='Matching ServedCell not found over F1-C')
    du.allow_alarm(fault_id='4592',
                   fault_name='BTS Reset Cause')

    du.config.add(dist_name='MRBTS-{}/MNL-1/CMD-1',
                  object_name='SWRESETREQ-1',
                  params_values={'swResetLevel': 'resetToTestLevel'},
                  wait=False)
    du.wait_for_reset()
    du.check_state(state='test_dedicated_state',
                   timeout=360)

    du.disallow_alarm(fault_id='4592',
                      fault_name='BTS Reset Cause')


@pretty_log
def exit_test_dedicated_state(du: Du):
    """
    Exits Test Dedicated State on given DU and cleans up its configuration if needed.
    :param du: DU which should not be in Test Dedicated State
    :raises UnexpectedState: if DU doesn't reach On Air State
    :raises ResultError: if any other step fails
    """
    _exit_test_dedicated_state(du)


@pretty_log
def cleanup_after_test_dedicated_state(du: Du, errors: ErrorHistory):
    """
    Restores DU to state from before entering Test Dedicated State.
    :param du: DU which entered Test Dedicated State
    :param errors: history of errors occurred during test execution
    """
    try:
        _exit_test_dedicated_state(du)
    except ResultError as exc:
        errors.add_from_exception(exc)


def _exit_test_dedicated_state(du: Du):
    log_info(f'Exiting Test Dedicated State on {du.name}',
             to_console=True)
    du.allow_alarm(fault_id='4592',
                   fault_name='BTS Reset Cause')

    if du.is_in_state(state='test_dedicated_state'):
        du.reset_and_wait_for_on_air()

    du.config.remove(dist_name='MRBTS-{}/MNL-1/CMD-1/SWRESETREQ-1')
    du.check_state(state='on_air',
                   timeout=300)

    du.disallow_alarm(fault_id='4592',
                      fault_name='BTS Reset Cause')
    du.cu.disallow_alarm(fault_id='7104',
                         fault_name='Matching ServedCell not found over F1-C')
